def find_decreasing_sequences(max_x_n, max_x_n_minus_1):
    results = []
    for xn in range(1, max_x_n + 1):
        for xn_minus_1 in range(xn + 1, max_x_n_minus_1 + 1):
            x = [xn_minus_1, xn]
            while True:
                prev_x = x[-1]
                prev_prev_x = x[-2]
                # x_{i-1} = (x_i^2 - x_{i+1}) / (x_{i+1} + 1)
                # Here x_{i+1} is x[-1], x_i is x[-2]
                # We want to find x_{i-1}
                # Wait, the index is i-1, i, i+1.
                # If our list is [x_k, x_{k-1}, ..., x_1]
                # Then x_{k-1} is x[-1], x_{k-2} is x[-2]
                # We want x_{k-3}
                # x_{k-3} = (x_{k-2}^2 - x_{k-1}) / (x_{k-1} + 1)
                # Wait, the original formula: x_{i-1}(x_{i+1} + 1) = x_i^2 - x_{i+1}
                # So x_{i-1} = (x_i^2 - x_{i+1}) / (x_{i+1} + 1)
                # In our list, x_{i+1} is x[-1], x_i is x[-2]
                # So we want x_{i-1} = (x[-2]^2 - x[-1]) / (x[-1] + 1)

                xi_plus_1 = x[-1]
                xi = x[-2]
                num = xi**2 - xi_plus_1
                den = xi_plus_1 + 1
                if num > 0 and num % den == 0:
                    next_x = num // den
                    if next_x > xi_plus_1:
                        x.insert(0, next_x)
                    else:
                        break
                else:
                    break
            if len(x) >= 5:
                results.append(x)
    return results

