def find_integer_k():
    for k in range(3, 100):
        for a2 in range(2, 1000):
            # a1^2 - (k*a2 + 2)a1 + (a2^2 - 2*a2 + 2) = 0
            # Discriminant D = (k*a2 + 2)^2 - 4(a2^2 - 2*a2 + 2)
            D = (k*a2 + 2)**2 - 4*(a2**2 - 2*a2 + 2)
            if D >= 0:
                sqrt_D = int(D**0.5)
                if sqrt_D**2 == D:
                    # a1 = (k*a2 + 2 +/- sqrt_D) / 2
                    for sign in [-1, 1]:
                        a1_num = (k*a2 + 2 + sign*sqrt_D)
                        if a1_num > 0 and a1_num % 2 == 0:
                            a1 = a1_num // 2
                            if a1 >= 2:
                                # Check if k = (a1^2 + a2^2 - 2a1 - 2a2 + 2) / (a1*a2)
                                k_check = (a1**2 + a2**2 - 2*a1 - 2*a2 + 2) / (a1*a2)
                                if k_check == k:
                                    return k, a1, a2
    return None

