def find_sequences(max_y1, max_y2, max_n):
    results = []
    for y1 in range(2, max_y1 + 1):
        for y2 in range(2, max_y2 + 1):
            y = [y1, y2]
            possible = True
            for i in range(len(y) - 1):
                next_y = (y[i]**2 - 2*y[i] + 2) // y[i-1]
                if (y[i]**2 - 2*y[i] + 2) % y[i-1] != 0 or next_y < 2:
                    possible = False
                    break
                y.append(next_y)
                if len(y) == max_n:
                    break
            if possible and len(y) >= max_n:
                results.append(y)
    return results

