def is_valid(m):
    # m = 2^a * product of p_i^e_i where p_i = 1 mod 4, a = 0 or 1
    if m == 1: return True
    temp_m = m
    if temp_m % 2 == 0:
        temp_m //= 2
    if temp_m % 2 == 0:
        return False

    d = 3
    while d * d <= temp_m:
        if temp_m % d == 0:
            if d % 4 == 3:
                return False
            while temp_m % d == 0:
                temp_m //= d
        d += 2
    if temp_m % 4 == 3:
        return False
    return True

