def check_k(k_max):
    for k in range(3, k_max):
        # D = (k^2-4)y2^2 + (4k+8)y2 - 4
        # We want D = m^2 for some y2.
        # This is a quadratic in y2. We can check y2 up to some limit.
        for y2 in range(2, 1000):
            D = (k**2 - 4) * y2**2 + (4*k + 8) * y2 - 4
            if D >= 0:
                m = int(D**0.5)
                if m*m == D:
                    # Found y2! Now find y1.
                    # y1^2 - (ky2+2)y1 + (y2^2-2y2+2) = 0
                    # y1 = ((ky2+2) +/- m) / 2
                    for y1 in [(k*y2 + 2 + m) // 2, (k*y2 + 2 - m) // 2]:
                        if y1 > 0 and y1**2 - (k*y2 + 2)*y1 + (y2**2 - 2*y2 + 2) == 0:
                            print(f"k={k}, y1={y1}, y2={y2}")
                            # Check if it's strictly increasing or decreasing
                            # k > 2 and y1, y2 > 0 means it's increasing if y2 > y1
                            # y2^2 - (ky1+2)y2 + (y1^2-2y1+2) = 0
                            # wait, we already have y1 and y2.
                            # y3 = (y2^2 - 2y2 + 2) / y1
                            y = [y1, y2]
                            while True:
                                num = y[-1]**2 - 2*y[-1] + 2
                                den = y[-2]
                                if num % den == 0:
                                    next_y = num // den
                                    if next_y >= 2:
                                        y.append(next_y)
                                    else:
                                        break
                                else:
                                    break
                            print(f"Sequence: {y}")
                            return True
    return False

print(check_k(20))

def find_decreasing_sequences(max_y1, max_y2):
    results = []
    for y1 in range(2, max_y1 + 1):
        for y2 in range(2, y1):
            y = [y1, y2]
            while True:
                num = y[-1]**2 - 2*y[-1] + 2
                den = y[-2]
                if num % den == 0:
                    next_y = num // den
                    if next_y >= 2:
                        y.append(next_y)
                        if len(y) >= 5:
                            results.append(y)
                        if next_y >= y[-1]: # Not strictly decreasing
                            break
                    else:
                        break
                else:
                    break
    return results

