def find_k_d():
    for k in range(1, 100):
        for d in range(1, k**2 + 2*k + 2):
            if (k**2 - 2*k + 2) % d == 0 and (k**2 + 2*k + 2) % (d+k) == 0:
                y3 = d + k
                y4 = y3 - k
                y2 = d + 2*k + (k**2 - 2*k + 2) // d
                y1 = (y2**2 - 2*y2 + 2) // y3
                y5 = y3 - (2*k+2) + (k**2 + 2*k + 2) // y3

                if y1 > y2 > y3 > y4 > y5 >= 2:
                    print(f"Found: k={k}, d={d}, y1={y1}, y2={y2}, y3={y3}, y4={y4}, y5={y5}")
                    return
    return None

